import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Shape, ExtrudeGeometry, Mesh, Color, PointLight, CircleGeometry, DoubleSide } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // Root object — adapter controls its position/rotation/scale from scenePosition.
  const root = new Group();
  root.name = 'pricing-badge-root';

  // Inner rig carries all local animation so we never fight the adapter's placement.
  const rig = new Group();
  rig.name = 'pricing-badge-rig';
  root.add(rig);

  const width = 1.3;
  const height = 0.42;
  const radius = height / 2;

  function buildCapsuleShape(w, h, r) {
    const shape = new Shape();
    const hw = Math.max(w / 2 - r, 0.001);
    shape.moveTo(-hw, -r);
    shape.lineTo(hw, -r);
    shape.absarc(hw, 0, r, -Math.PI / 2, Math.PI / 2, false);
    shape.lineTo(-hw, r);
    shape.absarc(-hw, 0, r, Math.PI / 2, (Math.PI * 3) / 2, false);
    return shape;
  }

  // Machined-metal capsule body — extruded + beveled, never a flat rect.
  const baseShape = buildCapsuleShape(width, height, radius);
  const bodyGeometry = new ExtrudeGeometry(baseShape, {
    depth: 0.1,
    bevelEnabled: true,
    bevelThickness: 0.02,
    bevelSize: 0.02,
    bevelSegments: 3,
    curveSegments: 24,
  });
  bodyGeometry.center();

  const bodyMaterial = new MeshPhysicalNodeMaterial({
    color: new Color(colors.ink),
    roughness: 0.55,
    metalness: 0.42,
    clearcoat: 0.2,
    clearcoatRoughness: 0.35,
  });

  const capsule = new Mesh(bodyGeometry, bodyMaterial);
  rig.add(capsule);

  // Accent edge light — a slightly larger emissive shell sitting just behind the body.
  const edgeShape = buildCapsuleShape(width * 1.06, height * 1.16, radius * 1.16);
  const edgeGeometry = new ExtrudeGeometry(edgeShape, {
    depth: 0.045,
    bevelEnabled: true,
    bevelThickness: 0.008,
    bevelSize: 0.008,
    bevelSegments: 2,
    curveSegments: 24,
  });
  edgeGeometry.center();

  const edgeMaterial = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 1.3,
    roughness: 0.4,
    metalness: 0.1,
  });
  const edge = new Mesh(edgeGeometry, edgeMaterial);
  edge.position.z = -0.055;
  rig.add(edge);

  // Local accent rim light — scene supplies ambient + key only.
  const rimLight = new PointLight(new Color(colors.accent), 1.1, 3, 2);
  rimLight.position.set(0.55, 0.25, 0.5);
  rig.add(rimLight);

  // Contact shadow for depth grounding.
  const shadowGeometry = new CircleGeometry(0.85, 32);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: new Color(0x000000),
    transparent: true,
    opacity: 0.42,
    side: DoubleSide,
    depthWrite: false,
  });
  const shadow = new Mesh(shadowGeometry, shadowMaterial);
  shadow.position.set(0, -0.02, -0.09);
  rig.add(shadow);

  let grainTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        grainTexture = tex;
        bodyMaterial.map = tex;
        bodyMaterial.needsUpdate = true;
      })
      .catch(() => {});
  }

  // Entrance — weighted settle, no linear easing on hero motion.
  const introTl = gsap.timeline();
  introTl.fromTo(
    rig.position,
    { y: -0.15 },
    { y: 0, duration: 0.7, ease: 'power3.out' },
    0
  );
  introTl.fromTo(
    rig.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    0
  );

  // Hover — subtle rise-in (0.15 units) per behavior spec.
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(rig.position, { y: 0.15, duration: 0.3, ease: 'power2.out' }, 0);
  hoverTl.to(rig.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.3, ease: 'power2.out' }, 0);
  hoverTl.to(edgeMaterial, { emissiveIntensity: 2.0, duration: 0.3, ease: 'power2.out' }, 0);

  // Click — press-down then weighted settle.
  const pressTl = gsap.timeline({ paused: true });
  pressTl.to(rig.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'power2.out' });
  pressTl.to(rig.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.6, ease: 'power4.out' });

  function onPointerEnter() {
    pressTl.pause(0);
    hoverTl.play();
  }
  function onPointerLeave() {
    hoverTl.reverse();
  }
  function onPointerDown() {
    pressTl.restart();
  }
  function onClick() {
    pressTl.restart();
    ctx.emit('hub-pricing.select', { nodeId: config.id ?? 'pricing-badge' });
  }

  root.userData.handlers = {
    pointerenter: onPointerEnter,
    pointerover: onPointerEnter,
    pointerleave: onPointerLeave,
    pointerout: onPointerLeave,
    pointerdown: onPointerDown,
    click: onClick,
  };

  root.userData.cleanup = function cleanup() {
    introTl.kill();
    hoverTl.kill();
    pressTl.kill();

    bodyGeometry.dispose();
    bodyMaterial.dispose();
    edgeGeometry.dispose();
    edgeMaterial.dispose();
    shadowGeometry.dispose();
    shadowMaterial.dispose();

    if (grainTexture && typeof grainTexture.dispose === 'function') {
      grainTexture.dispose();
    }

    rig.remove(rimLight);
    root.userData.handlers = {};
  };

  return root;
}
